#!/usr/bin/env node
/**
 * Does every migration the CMS imports actually exist?
 *
 * cms/src/migrations/index.ts is generated by scanning the migrations
 * directory. This drive is exFAT and scatters AppleDouble sidecars (`._name`)
 * beside real files, so the generator picks one up, writes
 *
 *   import * as migration_._20260831_162045_... from './._20260831_162045_...'
 *
 * and two things go wrong at once. The identifier is not valid JavaScript, and
 * the file it points at is never committed because `._*` is ignored. Locally
 * the sidecar exists so nothing looks broken; on Railway it does not, and the
 * CMS build fails on an import of a file that is not there.
 *
 * That has now shipped three times: 4b314b52, 36a07527, and fbd8edab on
 * 31 August 2026, which cost an afternoon of "the deploy keeps failing" with no
 * obvious cause, because the site itself deploys fine and only the CMS breaks.
 *
 * The npm scripts already delete `._*` before running a migration. That does
 * not help, because the sidecar is recreated by the filesystem afterwards and
 * the damage is in the committed index, not on disk.
 *
 *   node scripts/check-migrations.mjs
 *
 * Exit 0 every import resolves, 1 a real finding, 2 could not check.
 */
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DIR = join(ROOT, 'cms', 'src', 'migrations');
const INDEX = join(DIR, 'index.ts');

if (!existsSync(INDEX)) {
    console.log(`Could NOT check: ${INDEX} is missing.`);
    console.log('That is not a pass.');
    process.exit(2);
}

const source = readFileSync(INDEX, 'utf8');
const imports = [...source.matchAll(/^import \* as (\S+) from '\.\/([^']+)';/gm)];

if (imports.length === 0) {
    console.log('Could NOT check: no migration imports found in the index.');
    process.exit(2);
}

const problems = [];

for (const [, identifier, file] of imports) {
    // An AppleDouble sidecar, or anything else that cannot be a JS identifier.
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(identifier)) {
        problems.push(`${identifier}  is not a valid identifier, so the file will not parse`);
        continue;
    }
    const ts = join(DIR, `${file}.ts`);
    if (!existsSync(ts)) {
        problems.push(`${file}  is imported but ${file}.ts does not exist`);
    }
}

// A migration on disk that nobody registered runs nowhere, which is the quieter
// half of the same mistake.
const onDisk = readdirSync(DIR)
    .filter((f) => f.endsWith('.ts') && f !== 'index.ts' && !f.startsWith('._'))
    .map((f) => f.replace(/\.ts$/, ''));
const registered = new Set(imports.map(([, , file]) => file));
for (const file of onDisk) {
    if (!registered.has(file)) problems.push(`${file}.ts exists but is not registered in index.ts, so it will never run`);
}

console.log(`Checked ${imports.length} import(s) against ${onDisk.length} migration file(s).`);

if (problems.length > 0) {
    console.log(`\n${problems.length} problem(s):\n`);
    problems.forEach((p) => console.log(`  ${p}`));
    console.log('\nThe CMS build fails on this and the site does not, so the only symptom is');
    console.log('a CMS deploy that keeps failing for no visible reason. Delete the "._" import');
    console.log('and its entry in the migrations array, then rebuild.');
    process.exit(1);
}

console.log('\nClean. Every migration is registered and every import resolves.');
